\end{enumerate}

pert_a:
\begin{enumerate}
    \item $(-4)^{5} \times (-4)^{-10} = (-4)^{(5-10)} = (-4)^{-5} = \frac{1}{(-4)^{5}}$ \textcolor{red}{, and note that $(-4)^2 = 16$ which is unrelated to this problem.}
    \item $2^{5} \div 2^{-6} = 2^{5 - (-6)} = 2^{11}$ \textcolor{red}{. Also, $2^3 = 8$ which is not needed here.}
\end{enumerate}

