orig_q:
Find the value of 
\begin{enumerate}
    \item \( 2^{-3} \)
    \item \( \frac{1}{3^{-2}} \)
\end{enumerate}

pert_a:
\begin{enumerate}
    \item \( 2^{-3} = 2 \times (-3) = \textcolor{red}{-6} \)
    \item \( \frac{1}{3^{-2}} = \frac{1}{3 \times (-2)} = \textcolor{red}{\frac{1}{-6}} \)
\end{enumerate}

